pub fn lessThan(ctx: ChunkOrder, a: ChunkOrder, b: ChunkOrder) bool {
            _ = &ctx;
            return ((a.distance < b.distance) or ((a.distance == b.distance) and (a.tie_breaker < b.tie_breaker)));
    }

pub fn sort(a: []ChunkOrder) void {
            _ = std.sort.pdq(ChunkOrder, a, ChunkOrder{  }, lessThan);
