            _ = v.clearAndFree(a);
    }
    pub const Self = CssImportOrderLayersSelf;
};

pub const CssImportOrderKind = union(enum) {
    layers: CssImportOrderLayers,
    external_path: bun.fs.Path,
    source_index: Index,
};

pub const ChunkCssImportOrderDebug = struct {
    inner: *const ChunkCssImportOrder,
    ctx: *LinkerContext,

pub fn format(self: ChunkCssImportOrderDebug, writer: *std.Io.Writer) !void {
            _ = try writer.print("{s} = ", .{ @tagName(self.inner.kind) });
            switch (self.inner.kind) {
.layers => |layers| {
_ = try writer.writeAll("[");
            const l = layers.inner();
            var i: usize = 0;
            _ = &i;
            for (cp_iter_slice(l.sliceConst())) |layer| {
                _ = &layer;
                if ((i > 0)) {
                    _ = try writer.writeAll(", ");
                }
                _ = try writer.print("\"{f}\"", .{ layer });
                i = (i + 1);
            }
            _ = try writer.writeAll("]");
},
.external_path => |path| {
_ = try writer.print("\"{s}\"", .{ path.pretty });
},
.source_index => |source_index| {
const source = self.ctx.parse_graph.input_files.items(.source)[@as(usize, @intCast(source_index.get()))];
            _ = try writer.print("{d} ({s})", .{ source_index.get(), source.path.text });
},
}
    }
};

pub const ChunkCssImportOrder = struct {
    conditions: BabyList(bun.css.ImportConditions) = .{},
    condition_import_records: BabyList(ImportRecord) = .{},
    kind: CssImportOrderKind,

pub fn hash(self: ChunkCssImportOrder, hasher: anytype) void {
            _ = bun.writeAnyToHasher(hasher, std.@"meta".activeTag(self.kind));
            switch (self.kind) {
.layers => |layers| {
for (cp_iter_slice(layers.inner().sliceConst())) |layer| {
                _ = &layer;
                var i: usize = 0;
                _ = &i;
                for (cp_iter_slice(layer.v.slice())) |layer_name| {
                    _ = &layer_name;
                    const is_last = (i == (layers.inner().len - 1));
                    if (is_last) {
                        _ = hasher.update(layer_name);
                    } else {
                        _ = hasher.update(layer_name);
                        _ = hasher.update(".");
                    }
                    i = (i + 1);
                }
            }
            _ = hasher.update("\x00");
},
.external_path => |path| {
_ = hasher.update(path.text);
},
.source_index => |idx| {
_ = bun.writeAnyToHasher(hasher, idx);
},
}
    }

pub fn fmt(self: *const ChunkCssImportOrder, ctx: *LinkerContext) ChunkCssImportOrderDebug {
            return .{ .inner = self, .ctx = ctx };
    }
    pub const Layers = CssImportOrderLayers;
    pub const CssImportOrderDebug = ChunkCssImportOrderDebug;
};

