};

pub const ChunkIntermediateOutput = union(enum) {
    pieces: bun.BabyList(ChunkOutputPiece),
    joiner: StringJoiner,
    empty: void,

pub fn allocatorForSize(size: usize) std.mem.Allocator {
            if ((size >= (512 * 1024))) {
                return std.heap.page_allocator;
            } else {
                return bun.default_allocator;
            }
    }

pub fn countClosingTags(content: []const u8, close_tag: []const u8) usize {
            const tag_suffix = close_tag[2..];
            var count: usize = 0;
            _ = &count;
            var remaining = content;
            _ = &remaining;
            while (strings.indexOf(remaining, "</")) |idx| {
                remaining = remaining[(idx + 2)..];
                if (((remaining.len >= tag_suffix.len) and strings.eqlCaseInsensitiveASCIIIgnoreLength(remaining[0..tag_suffix.len], tag_suffix))) {
                    count = (count + 1);
                    remaining = remaining[tag_suffix.len..];
                }
            }
            return count;
    }

pub fn memcpyEscapingClosingTags(dest: []u8, content: []const u8, close_tag: []const u8) usize {
            const tag_suffix = close_tag[2..];
            var remaining = content;
            _ = &remaining;
            var dst: usize = 0;
            _ = &dst;
            while (strings.indexOf(remaining, "</")) |idx| {
                _ = @memcpy(dest[dst..][0..idx], remaining[0..idx]);
                dst = (dst + idx);
                remaining = remaining[(idx + 2)..];
                if (((remaining.len >= tag_suffix.len) and strings.eqlCaseInsensitiveASCIIIgnoreLength(remaining[0..tag_suffix.len], tag_suffix))) {
                    dest[cp_cast_int(usize, dst)] = 60;
                    dest[cp_cast_int(usize, (dst + 1))] = 92;
                    dest[cp_cast_int(usize, (dst + 2))] = 47;
                    dst = (dst + 3);
                } else {
                    dest[cp_cast_int(usize, dst)] = 60;
                    dest[cp_cast_int(usize, (dst + 1))] = 47;
                    dst = (dst + 2);
                }
            }
            _ = @memcpy(dest[dst..][0..remaining.len], remaining);
            dst = (dst + remaining.len);
            return dst;
    }

pub fn getSize(self: ChunkIntermediateOutput) usize {
            return (switch (self) {
.pieces => |pieces| brk: {
            var total: usize = 0;
            _ = &total;
            for (cp_iter_slice(pieces.slice())) |piece| {
                _ = &piece;
                total = (total + piece.data_len);
            }
            break :brk total;
},
.joiner => |joiner| joiner.len,
.empty => 0,
});
    }

pub fn code(self: *ChunkIntermediateOutput, allocator_to_use: ?std.mem.Allocator, parse_graph: *const Graph, linker_graph: *const LinkerGraph, import_prefix: []const u8, chunk: *Chunk, chunks: []Chunk, display_size: ?*usize, force_absolute_path: bool, enable_source_map_shifts: bool) bun.OOM!CodeResult {
            return (switch (enable_source_map_shifts) {
inline else => |source_map_shifts| self.codeWithSourceMapShifts(allocator_to_use, parse_graph, linker_graph, import_prefix, chunk, chunks, display_size, force_absolute_path, source_map_shifts, null),
});
    }

pub fn codeStandalone(self: *ChunkIntermediateOutput, allocator_to_use: ?std.mem.Allocator, parse_graph: *const Graph, linker_graph: *const LinkerGraph, import_prefix: []const u8, chunk: *Chunk, chunks: []Chunk, display_size: ?*usize, force_absolute_path: bool, enable_source_map_shifts: bool, standalone_chunk_contents: ?[]const ?[]const u8) bun.OOM!CodeResult {
            return (switch (enable_source_map_shifts) {
inline else => |source_map_shifts| self.codeWithSourceMapShifts(allocator_to_use, parse_graph, linker_graph, import_prefix, chunk, chunks, display_size, force_absolute_path, source_map_shifts, standalone_chunk_contents),
});
    }

pub fn codeWithSourceMapShifts(self: *ChunkIntermediateOutput, allocator_to_use: ?std.mem.Allocator, graph: *const Graph, linker_graph: *const LinkerGraph, import_prefix: []const u8, chunk: *Chunk, chunks: []Chunk, display_size: ?*usize, force_absolute_path: bool, comptime enable_source_map_shifts: bool, standalone_chunk_contents: ?[]const ?[]const u8) bun.OOM!CodeResult {
            const additional_files = graph.input_files.items(.additional_files);
            const unique_key_for_additional_files = graph.input_files.items(.unique_key_for_additional_file);
            const relative_platform_buf = bun.path_buffer_pool.get();
            defer {
            _ = bun.path_buffer_pool.put(relative_platform_buf);
            }
            switch (self.*) {
.pieces => |pieces| {
const entry_point_chunks_for_scb = linker_graph.files.items(.entry_point_chunk_index);
            var shift: SourceMap.SourceMapShifts = (if (enable_source_map_shifts) SourceMap.SourceMapShifts{ .after = .{}, .before = .{} } else undefined);
            _ = &shift;
            var shifts: std.ArrayList(SourceMap.SourceMapShifts) = (if (enable_source_map_shifts) try std.ArrayList(SourceMap.SourceMapShifts).initCapacity(bun.default_allocator, (pieces.len + 1)) else undefined);
            _ = &shifts;
            if (enable_source_map_shifts) {
                _ = shifts.appendAssumeCapacity(shift);
            }
            var count: usize = 0;
            _ = &count;
            var from_chunk_dir = ((std.fs.path.dirnamePosix(chunk.final_rel_path)) orelse (""));
            _ = &from_chunk_dir;
            if (strings.eqlComptime(from_chunk_dir, ".")) {
                from_chunk_dir = "";
            }
            const urls_for_css: []const []const u8 = (if ((standalone_chunk_contents != null)) graph.ast.items(.url_for_css) else &.{});
            for (cp_iter_slice(pieces.slice())) |piece| {
                _ = &piece;
                count = (count + piece.data_len);
                switch (piece.query.kind) {
.chunk, .asset, .scb, .html_import => {
const index = piece.query.index;
                if (standalone_chunk_contents) |scc| {
                    _ = &scc;
                    switch (piece.query.kind) {
.chunk => {
if (scc[@as(usize, @intCast(index))]) |content| {
                        _ = &content;
                        count = (count + (content.len + ChunkIntermediateOutput.countClosingTags(content, chunks[@as(usize, @intCast(index))].closingTagForContent())));
                        continue;
                    }
},
.asset => {
if (((index < urls_for_css.len) and (urls_for_css[@as(usize, @intCast(index))].len > 0))) {
                        count = (count + urls_for_css[@as(usize, @intCast(index))].len);
                        continue;
                    }
},
else => {

},
}
                }
                const file_path = (switch (piece.query.kind) {
.asset => brk: {
                const files = additional_files[@as(usize, @intCast(index))];
                if ((!(files.len > 0))) {
                    _ = Output.panic("Internal error: missing asset file", &.{});
                }
                const output_file = (files.last()).?.output_file;
                break :brk graph.additional_output_files.items[@as(usize, @intCast(output_file))].dest_path;
},
.chunk => chunks[@as(usize, @intCast(index))].final_rel_path,
.scb => chunks[@as(usize, @intCast(entry_point_chunks_for_scb[@as(usize, @intCast(index))]))].final_rel_path,
.html_import => {
{
                    count = (count + std.fmt.count("{f}", .{ HTMLImportManifest.formatEscapedJSON(.{ .index = index, .graph = graph, .chunks = chunks, .linker_graph = linker_graph }) }));
                    continue;
                }
},
.none => unreachable,
});
                const cheap_normalizer = cheapPrefixNormalizer(import_prefix, (if (((from_chunk_dir.len == 0) or force_absolute_path)) file_path else bun.path.relativePlatformBuf(relative_platform_buf, from_chunk_dir, file_path, .posix, false)));
                count = (count + (cheap_normalizer[0].len + cheap_normalizer[1].len));
},
.none => {

},
}
            }
            if (display_size) |amt| {
                _ = &amt;
                amt.* = count;
            }
            const debug_id_len = (if ((enable_source_map_shifts and FeatureFlags.source_map_debug_id)) std.fmt.count("\n//# debugId={f}\n", .{ bun.SourceMap.DebugIDFormatter{ .id = chunk.isolated_hash } }) else 0);
            const total_buf = try ((allocator_to_use) orelse (ChunkIntermediateOutput.allocatorForSize(count))).alloc(u8, (count + debug_id_len));
            var remain = total_buf;
            _ = &remain;
            for (cp_iter_slice(pieces.slice())) |piece| {
                _ = &piece;
                const data = piece.data();
                if (enable_source_map_shifts) {
                    var data_offset: SourceMap.LineColumnOffset = .{};
                    _ = &data_offset;
                    _ = data_offset.advance(data);
                    _ = shift.before.add(data_offset);
